import { notebooks as notebooksApi } from '@/api/endpoints.js';
import type { ApiImportJob } from '@/api/types.js';
import { t } from '@/i18n/index.js';
import { isApiError } from '@/api/errors.js';
import { overImportLimit, useConfig } from '@/lib/useConfig.js';
import { ImportError } from './transfer/parse.js';
import { pollDelay } from '@/features/ai/poll.js';

/**
 * Whether a file is SQLite, from its own first bytes rather than its name:
 * a Kindle's vocab.db is often copied off the device under another name.
 */
export async function isSqlite(file: File): Promise<boolean> {
  const magic = 'SQLite format 3';
  const head = await file.slice(0, magic.length).text();
  return head === magic;
}

/**
 * How long a server-side import is watched before giving up on watching (the
 * import itself carries on). The looks follow the AI job's schedule — 1, 2,
 * 3, then every 5 seconds — rather than one every 600 ms.
 */
const IMPORT_WATCH_MS = 60_000;

/** Watches a server import to the end, or until it is clearly stuck. */
export async function waitForImport(jobId: string): Promise<ApiImportJob> {
  let job = await notebooksApi.importStatus(jobId);
  let watched = 0;
  for (let attempt = 0; watched < IMPORT_WATCH_MS; attempt += 1) {
    if (job.status === 'done' || job.status === 'failed') return job;
    const wait = pollDelay(attempt);
    await new Promise((resolve) => setTimeout(resolve, wait));
    watched += wait;
    job = await notebooksApi.importStatus(jobId);
  }
  return job;
}

/** The message for a file that could not be read, by why. */
export function importErrorMessage(cause: unknown): string {
  if (cause instanceof ImportError) {
    if (cause.message === 'binary') return t('settings.importNotText');
    if (cause.message === 'spreadsheet') return t('settings.importSpreadsheet');
    if (cause.message === 'long highlights') return t('settings.importClippingsLong');
    if (cause.message === 'encoding') return t('settings.importEncoding');
    return t('settings.importUnreadable');
  }
  return t('error.generic');
}

/**
 * What the file pickers offer. The extensions are for browsers; the media
 * types are for Android, whose picker the app shell builds from media types
 * alone: an extension it has no type for (.apkg, .colpkg, .db) is dropped,
 * and without `application/octet-stream`, which is how Android labels a
 * file it does not know, an Anki deck or a Kindle's vocab.db could not be
 * chosen at all. Excel workbooks are read too.
 */
export const IMPORT_ACCEPT = [
  '.apkg',
  '.colpkg',
  '.json',
  '.csv',
  '.tsv',
  '.txt',
  '.db',
  '.xlsx',
  'application/json',
  'text/csv',
  'text/comma-separated-values',
  'text/tab-separated-values',
  'text/plain',
  'application/zip',
  'application/x-zip-compressed',
  'application/octet-stream',
  'application/vnd.sqlite3',
  'application/x-sqlite3',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
].join(',');

/**
 * Why a file read on the server did not import, from the job's own error.
 * The server words its errors from fixed sentences (format.ErrTooLarge,
 * format.ErrEmpty), so their opening words tell the cases apart.
 */
export function serverImportFailure(job: ApiImportJob, source: 'anki' | 'kindle'): string {
  const error = job.error ?? '';
  if (/too large/i.test(error)) return t('settings.importTooLarge');
  if (source === 'anki' && /no entries/i.test(error)) return t('settings.importAnkiEmpty');
  return t(source === 'anki' ? 'settings.importAnkiUnreadable' : 'settings.importUnreadable');
}

/** A file read on the server that is too large to send, said before any upload. */
export class FileTooLarge extends Error {}

/**
 * A file sent while the device said it was online whose upload never got
 * an answer: the connection dropped or was cut off on the way. Until
 * 24 Oct 2026 this was reported as "offline", which hid the server cutting
 * slow uploads off after 30 seconds (two Anki decks from Android, 22 Oct).
 */
export class UploadInterrupted extends Error {}

/**
 * Whether the device itself says it has no connection. `navigator.onLine`
 * is only trusted when it says false: true means a network interface is up,
 * not that the server can be reached.
 */
export function deviceOffline(): boolean {
  return typeof navigator !== 'undefined' && !navigator.onLine;
}

/**
 * Sends a file to be read on the server, after checking it against the
 * server's upload cap: a file over it is refused here at once instead of
 * after an upload the server cuts off, which a phone may never hear back
 * from. A send that fails without an answer is offline only when the device
 * says so; otherwise the upload was interrupted.
 */
export async function sendImport(
  notebookId: string,
  source: 'anki' | 'kindle',
  file: File,
): Promise<ApiImportJob> {
  if (overImportLimit(file.size)) throw new FileTooLarge();
  try {
    return await notebooksApi.importFile(notebookId, source, file);
  } catch (cause) {
    if (isApiError(cause, 'offline') && !deviceOffline()) throw new UploadInterrupted();
    throw cause;
  }
}

/** The upload cap in whole megabytes, when the server has said it. */
function limitMb(): number | undefined {
  const limit = useConfig.getState().importMaxBytes;
  return limit === undefined ? undefined : Math.floor(limit / (1 << 20));
}

/** The words for a file over the upload cap. */
function tooLargeMessage(source: 'anki' | 'kindle' | undefined): string {
  const mb = limitMb();
  if (source === 'anki' && mb !== undefined) return t('settings.importAnkiTooLarge', { mb });
  return t('settings.importTooLarge');
}

/** Why sending a file to the server failed. */
export function uploadFailure(cause: unknown, source?: 'anki' | 'kindle'): string {
  if (cause instanceof FileTooLarge) return tooLargeMessage(source);
  if (cause instanceof UploadInterrupted) return t('settings.importInterrupted');
  if (isApiError(cause, 'offline')) return t('settings.importNeedsNetwork');
  // The server answers `file_too_large` for a file over its upload limit.
  if (isApiError(cause) && cause.problem?.code === 'file_too_large') return tooLargeMessage(source);
  if (isApiError(cause, 'server')) return t('settings.importServerTrouble');
  return t('error.generic');
}
