import { useState } from 'react';
import { Button } from '@/components/ui/Button.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t } from '@/i18n/index.js';
import styles from './ImportPreview.module.css';

/**
 * Paste a list instead of choosing a file. Quizlet's export is a box of
 * text to copy, and saving that as a file on a phone is close to
 * impossible; pasted, it goes through the same reader a file does (tab or
 * comma between word and meaning, one card a line), and then through the
 * same check before anything is written.
 *
 * This is the list somebody already has. Picking new words out of a text
 * they are reading is the notebook's Paste a text, a different thing.
 */
export function PasteListSheet({
  onRead,
  onClose,
}: {
  /** Called with the pasted text; the caller parses it and shows the check. */
  onRead: (text: string) => void;
  onClose: () => void;
}): React.JSX.Element {
  const [text, setText] = useState('');
  return (
    <Sheet title={t('import.pasteTitle')} onClose={onClose}>
      <div className={styles.body}>
        <p className={styles.lead}>{t('import.pasteLead')}</p>
        <textarea
          className={styles.input}
          value={text}
          dir="auto"
          rows={8}
          placeholder={t('import.pastePlaceholder')}
          aria-label={t('import.pasteTitle')}
          autoFocus
          onChange={(event) => {
            setText(event.target.value);
          }}
        />
        <Button
          block
          size="large"
          disabled={text.trim() === ''}
          onClick={() => {
            onRead(text);
          }}
        >
          {t('import.pasteRead')}
        </Button>
      </div>
    </Sheet>
  );
}
