/**
 * Reading an Excel workbook (.xlsx, as Excel, Google Sheets and Numbers
 * save one) into rows of cells, on this device.
 *
 * A workbook is a zip of XML: the sheets, a table of the strings they
 * share, and the workbook's list of sheets in order. Only cell text is
 * wanted, so formulas are read by their last value, styles are ignored,
 * and a number is the digits the file holds. Every visible sheet is read;
 * the importer files a sheet's words under the sheet's name when there is
 * more than one.
 */
import { ImportError } from './parse.js';
import { readText, zipEntries } from './zip.js';

export interface Sheet {
  name: string;
  /** Rows of cells, columns in place: a missing cell is an empty string. */
  rows: string[][];
}

/** Whether a zip is a workbook, from the entries it holds. */
export function isWorkbook(names: readonly string[]): boolean {
  return names.includes('xl/workbook.xml');
}

export async function readWorkbook(bytes: Uint8Array): Promise<Sheet[]> {
  const entries = zipEntries(bytes);
  const workbook = await readText(bytes, entries, 'xl/workbook.xml');
  if (workbook === undefined) throw new ImportError('spreadsheet');
  const rels = (await readText(bytes, entries, 'xl/_rels/workbook.xml.rels')) ?? '';
  const shared = sharedStrings((await readText(bytes, entries, 'xl/sharedStrings.xml')) ?? '');

  const targets = new Map<string, string>();
  for (const tag of rels.match(/<(?:\w+:)?Relationship\b[^>]*>/g) ?? []) {
    const id = attr(tag, 'Id');
    const target = attr(tag, 'Target');
    if (id !== undefined && target !== undefined) targets.set(id, sheetPath(target));
  }

  const sheets: Sheet[] = [];
  for (const tag of workbook.match(/<(?:\w+:)?sheet\b[^>]*>/g) ?? []) {
    if ((attr(tag, 'state') ?? 'visible') !== 'visible') continue;
    const id = attr(tag, 'r:id') ?? attrEndingWith(tag, ':id');
    const path = id === undefined ? undefined : targets.get(id);
    if (path === undefined) continue;
    const xml = await readText(bytes, entries, path);
    if (xml === undefined) continue;
    sheets.push({ name: decode(attr(tag, 'name') ?? ''), rows: sheetRows(xml, shared) });
  }
  return sheets;
}

/** "worksheets/sheet1.xml" or "/xl/worksheets/sheet1.xml" → "xl/worksheets/sheet1.xml". */
function sheetPath(target: string): string {
  if (target.startsWith('/')) return target.slice(1);
  return `xl/${target.replace(/^\.\//, '')}`;
}

/**
 * The shared string table. A rich-text string is several runs, joined; a
 * phonetic reading (`<rPh>`, which Japanese Excel adds above kanji) is not
 * part of the text and is left out.
 */
function sharedStrings(xml: string): string[] {
  const out: string[] = [];
  for (const match of xml.matchAll(/<(?:\w+:)?si\b[^>]*>([\s\S]*?)<\/(?:\w+:)?si>/g)) {
    out.push(runsText(match[1] ?? ''));
  }
  return out;
}

function runsText(xml: string): string {
  const withoutReadings = xml.replace(/<(?:\w+:)?rPh\b[\s\S]*?<\/(?:\w+:)?rPh>/g, '');
  let text = '';
  for (const match of withoutReadings.matchAll(/<(?:\w+:)?t\b[^>]*?(?:\/>|>([\s\S]*?)<\/(?:\w+:)?t>)/g)) {
    text += decode(match[1] ?? '');
  }
  return text;
}

function sheetRows(xml: string, shared: readonly string[]): string[][] {
  const rows: string[][] = [];
  for (const rowMatch of xml.matchAll(/<(?:\w+:)?row\b([^>]*?)(?:\/>|>([\s\S]*?)<\/(?:\w+:)?row>)/g)) {
    const cells: string[] = [];
    let nextColumn = 0;
    for (const cellMatch of (rowMatch[2] ?? '').matchAll(
      /<(?:\w+:)?c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/(?:\w+:)?c>)/g,
    )) {
      const attrs = cellMatch[1] ?? '';
      const body = cellMatch[2] ?? '';
      const ref = attr(attrs, 'r');
      const column = ref === undefined ? nextColumn : columnIndex(ref);
      nextColumn = column + 1;
      const value = cellValue(attr(attrs, 't'), body, shared);
      while (cells.length < column) cells.push('');
      cells[column] = value;
    }
    const ref = attr(rowMatch[1] ?? '', 'r');
    const at = ref === undefined ? rows.length : Number.parseInt(ref, 10) - 1;
    // Rows the file skips are empty rows in the sheet; they are kept as
    // empty so nothing downstream mistakes a gap for the end.
    while (rows.length < at) rows.push([]);
    rows.push(cells);
  }
  return rows;
}

function cellValue(type: string | undefined, body: string, shared: readonly string[]): string {
  if (type === 'inlineStr') {
    const inline = /<(?:\w+:)?is\b[^>]*>([\s\S]*?)<\/(?:\w+:)?is>/.exec(body);
    return runsText(inline?.[1] ?? '');
  }
  const raw = decode(/<(?:\w+:)?v\b[^>]*>([\s\S]*?)<\/(?:\w+:)?v>/.exec(body)?.[1] ?? '');
  if (type === 's') return shared[Number.parseInt(raw, 10)] ?? '';
  if (type === 'b') return raw === '1' ? 'TRUE' : raw === '0' ? 'FALSE' : raw;
  return raw;
}

/** "C12" → 2. */
function columnIndex(ref: string): number {
  let column = 0;
  for (const char of ref.toUpperCase()) {
    const code = char.charCodeAt(0);
    if (code < 65 || code > 90) break;
    column = column * 26 + (code - 64);
  }
  return Math.max(0, column - 1);
}

function attr(tag: string, name: string): string | undefined {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = new RegExp(`(?:^|\\s)${escaped}\\s*=\\s*("([^"]*)"|'([^']*)')`).exec(tag);
  return match === null ? undefined : (match[2] ?? match[3]);
}

/** The value of the first attribute whose name ends with `suffix` (a relationship id under any prefix). */
function attrEndingWith(tag: string, suffix: string): string | undefined {
  const match = new RegExp(`\\s[\\w]+${suffix}\\s*=\\s*"([^"]*)"`).exec(tag);
  return match?.[1];
}

const XML_ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };

/** XML's five entities and numeric references; `_x000D_` is Excel's escape for a control character. */
function decode(text: string): string {
  return text
    .replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (entity, name: string) => {
      if (name.startsWith('#')) {
        const code =
          name[1]?.toLowerCase() === 'x'
            ? Number.parseInt(name.slice(2), 16)
            : Number.parseInt(name.slice(1), 10);
        return Number.isFinite(code) && code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : entity;
      }
      return XML_ENTITIES[name.toLowerCase()] ?? entity;
    })
    .replace(/_x([0-9a-f]{4})_/gi, (_, hex: string) => String.fromCharCode(Number.parseInt(hex, 16)));
}
