/**
 * How an import this app ran itself ended, for the operators (the data
 * plan, owner 22 Oct 2026): the kind of file, done / nothing new / failed, a
 * short code and the row counts. Never the file's name, never a word. The
 * server keeps the row without the account, so "the import did not work"
 * can be counted after the person who said it has gone.
 *
 * A file the server reads (an Anki deck, a Kindle's vocab.db) reports its
 * own end there; only a failure to send it is reported from here. Sent once
 * and never retried: a failure, or a server without the endpoint, changes
 * nothing for the learner.
 *
 * While the server says it keeps imported files for a day
 * (`importFileCapture`), the original file goes with the outcome, once, in
 * the background, within the upload cap: a pasted list as `pasted.txt`. Only
 * when the import did not work as expected (it failed, or rows were skipped
 * or could not be read), as lexpad.app/privacy says; never after a clean,
 * fully successful import. Nothing waits for it and nothing is said about it
 * here.
 */
import { me } from '@/api/endpoints.js';
import type { ApiImportOutcomeInput } from '@/api/types.js';
import { isApiError } from '@/api/errors.js';
import { capturesImportFile } from '@/lib/useConfig.js';
import { FileTooLarge, UploadInterrupted } from './importJob.js';
import { ImportError } from './transfer/parse.js';
import type { ImportSource } from './transfer/read.js';

export type ImportKind = ApiImportOutcomeInput['kind'];

/** The separator a Kindle's My Clippings.txt puts between highlights. */
const CLIPPING_SEPARATOR = '==========';

/** The kind of a file the app read, from what was read rather than its name. */
export function kindOf(read: ImportSource): ImportKind {
  if (read.kind === 'server') return read.source;
  if (read.kind === 'sheets') return 'xlsx';
  const text = read.text.trimStart();
  if (text.startsWith('[') || text.startsWith('{')) return 'json';
  if (text.includes(CLIPPING_SEPARATOR)) return 'clippings';
  return 'csv';
}

/** The short code for why an import failed. */
export function failureCode(cause: unknown): string {
  if (cause instanceof FileTooLarge) return 'too_large';
  if (cause instanceof ImportError) {
    switch (cause.message) {
      case 'binary':
        return 'binary';
      case 'spreadsheet':
        return 'spreadsheet';
      case 'long highlights':
        return 'long_highlights';
      case 'encoding':
        return 'encoding';
      case 'empty':
      case 'no words':
        return 'empty';
      default:
        return 'unreadable';
    }
  }
  // Offline only when the device said so; an upload that got no answer
  // while online was interrupted (sendImport tells them apart).
  if (cause instanceof UploadInterrupted) return 'interrupted';
  if (isApiError(cause, 'offline')) return 'offline';
  if (isApiError(cause) && cause.problem?.code === 'file_too_large') return 'too_large';
  if (isApiError(cause, 'server')) return 'server_error';
  if (isApiError(cause)) return 'upload_failed';
  return 'other';
}

/** The original file an import was given, for the server's one-day copy. */
export interface ImportedFile {
  data: Blob;
  name: string;
}

/** The name a pasted list is kept under. */
export const PASTED_NAME = 'pasted.txt';

/** A pasted list as the file it is kept as. */
export function pastedFile(text: string): ImportedFile {
  return { data: new Blob([text], { type: 'text/plain;charset=utf-8' }), name: PASTED_NAME };
}

/**
 * Whether an import did not work as expected, the only time its file may be
 * kept (privacy page, owner 23 Oct 2026): it failed, nothing new came of it,
 * or some of its rows were skipped. A clean import that added every row never
 * qualifies.
 */
export function wentWrong(outcome: ApiImportOutcomeInput): boolean {
  if (outcome.outcome !== 'done') return true;
  return (outcome.rowsSkipped ?? 0) > 0;
}

/**
 * Sends one outcome, fire and forget, and the file too when the server keeps
 * them and the import went wrong.
 */
export function reportImport(outcome: ApiImportOutcomeInput, file?: ImportedFile): void {
  try {
    void me.reportImportOutcome(outcome).catch(() => undefined);
    if (file !== undefined && wentWrong(outcome) && capturesImportFile(file.data.size)) {
      void me.keepImportFile(file.data, file.name, outcome).catch(() => undefined);
    }
  } catch {
    // A report is never worth an error on the import screen.
  }
}

/** Reports a failed import of this kind, with the cause's code. */
export function reportImportFailure(kind: ImportKind, cause: unknown, file?: ImportedFile): void {
  reportImport({ kind, outcome: 'failed', errorCode: failureCode(cause) }, file);
}
