/**
 * Reading a file the user hands us.
 *
 * Four shapes are accepted, told apart by their own structure rather than
 * by file extension: the prototype's handwritten-notebook JSON (an array of
 * snake_case entries), a Lexpad export (an object with a `words` array), a
 * Kindle's My Clippings.txt, and a two-column CSV (which also covers
 * tab-separated Quizlet and Anki exports). The field mapping
 * mirrors the server's importer in
 * `apps/api/internal/app/transfer/format`, so a file imported here and the
 * same file imported there produce the same notebook.
 *
 * A Kindle's other file, vocab.db, is SQLite and is read by the server
 * instead; Settings sends that one on rather than parsing it here.
 */
import {
  LANGUAGE_INFO,
  LANGUAGES,
  normalizeHeadword,
  scriptOf,
  scriptOfLanguage,
  type LanguageCode,
  type Progress,
  type Source,
  type Word,
  LEVELS,
} from '@lexpad/core';
import type { ImportRow } from '@/db/mutations.js';
import { MAX_HEADWORD_CHARS } from '@/features/notebook/spelling.js';
import type { StoredWord } from '@/db/schema.js';

/** One parsed entry, with the reference its own file used for relations. */
/** What the parsers produce; the import mutation numbers and dates them. */
export type ParsedRow = ImportRow;

export interface ParsedFile {
  rows: ParsedRow[];
  targetLang: LanguageCode | undefined;
  meaningLang: LanguageCode | undefined;
  /** Entries the file contained but that carried no headword. */
  skipped: number;
}

export class ImportError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ImportError';
  }
}

type Meanings = NonNullable<Word['meanings']>;
type Phrases = NonNullable<Word['expressions']>;

/**
 * Reads a file, choosing the parser from what is actually inside it. The
 * name is not consulted: a list is the same list as .txt or as .csv.
 */
export function parseFile(_name: string, text: string, hints?: LanguageHints): ParsedFile {
  const trimmed = text.trim();
  if (trimmed === '') throw new ImportError('empty');
  if (trimmed.startsWith('[')) return parseLegacy(trimmed);
  if (trimmed.startsWith('{')) return parseLexpad(trimmed);
  // Before the CSV branch: a clippings file is full of commas and would
  // otherwise be read as one very wide spreadsheet.
  if (isClippings(trimmed)) return parseClippings(trimmed);
  // Anything else that is text is a list: two columns, or one word a line,
  // whatever the file is called. A plain word list saved as .txt is the
  // same list as one saved as .csv.
  return parseCsv(trimmed, hints);
}

/* ---------------------------------------------------------------- legacy */

interface LegacyEntry {
  id?: number;
  page?: number;
  english?: string;
  farsi_original?: string;
  raw_note?: string;
  correction?: string | null;
  pos?: string;
  category?: string;
  level?: string;
  pronunciation?: string;
  tricky_spelling?: boolean;
  spelling_note?: string | null;
  meanings?: {
    meaning_fa?: string;
    meaning_en?: string;
    examples?: { en?: string; fa?: string }[];
  }[];
  expressions?: { en?: string; fa?: string }[];
  collocations?: string[];
  usage_note?: string;
  related_ids?: number[];
  related_note?: string;
  related_words?: { en?: string; fa?: string }[];
}

/** The prototype's notebook: an array of snake_case entries. */
export function parseLegacy(text: string): ParsedFile {
  const entries = asArray(text) as LegacyEntry[];
  const rows: ParsedRow[] = [];
  let skipped = 0;

  entries.forEach((entry, index) => {
    const headword = clean(entry.english);
    if (headword === '') {
      skipped += 1;
      return;
    }

    const meanings: Meanings = [];
    for (const meaning of entry.meanings ?? []) {
      const text_ = clean(meaning.meaning_fa);
      if (text_ === '') continue;
      const gloss = clean(meaning.meaning_en);
      meanings.push({
        meaning: text_,
        ...(gloss === '' ? {} : { gloss }),
        examples: (meaning.examples ?? []).flatMap((example) => {
          const sentence = clean(example.en);
          if (sentence === '') return [];
          const translation = clean(example.fa);
          return [{ sentence, ...(translation === '' ? {} : { translation }) }];
        }),
      });
    }
    // A page the reader could not transcribe still keeps its own words.
    const original = clean(entry.farsi_original);
    if (meanings.length === 0 && original !== '') meanings.push({ meaning: original, examples: [] });

    const usageNote = clean(entry.usage_note) || clean(entry.raw_note);
    const word: ParsedRow['word'] = {
      headword,
      category: clean(entry.category) || 'general',
      source: 'import',
      meanings,
      expressions: phrases(entry.expressions),
      collocations: (entry.collocations ?? []).map(clean).filter((value) => value !== ''),
      relatedWords: phrases(entry.related_words),
      relatedWordIds: [],
    };
    assign(word, 'pos', clean(entry.pos));
    assign(word, 'pronunciation', clean(entry.pronunciation));
    assign(word, 'spellingNote', clean(entry.spelling_note));
    assign(word, 'originalMeaning', original);
    assign(word, 'correction', clean(entry.correction));
    assign(word, 'usageNote', usageNote);
    assign(word, 'relatedNote', clean(entry.related_note));
    const level = asLevel(entry.level);
    if (level !== undefined) word.level = level;
    if (entry.tricky_spelling === true) word.trickySpelling = true;

    rows.push({
      ref: String(entry.id ?? index + 1),
      word,
      relatedRefs: (entry.related_ids ?? []).map(String),
    });
  });

  if (rows.length === 0) throw new ImportError('no words');
  return { rows, targetLang: 'en', meaningLang: 'fa', skipped };
}

/* ------------------------------------------------------------- lexpad */

interface LexpadFile {
  version?: unknown;
  words?: (Partial<StoredWord> & { id?: string; progress?: Progress })[];
  notebook?: { targetLang?: string; meaningLang?: string };
}

/** The export versions this app reads (export.ts writes the newest). */
const LEXPAD_VERSIONS: readonly unknown[] = [undefined, 1, 2];

/**
 * The part of a word's learning state an import keeps: everything but the
 * memory the server worked out (stability and difficulty). The server never
 * takes those from a push, so a copy here would only disagree with it until
 * the next pull; without them, Boxes and Smart alike start the word from its
 * box, on both sides. The lapse count stays as files have always carried it.
 */
function scheduleOnly(progress: Progress): Progress {
  const { stabilityE4: _stability, difficultyE4: _difficulty, ...kept } = progress;
  return kept;
}

const SOURCES: readonly Source[] = ['manual', 'ai', 'assistant', 'import', 'shared'];

/** A file this app exported. Its words are already in the local shape. */
export function parseLexpad(text: string): ParsedFile {
  const parsed = asObject(text) as LexpadFile;
  if (!Array.isArray(parsed.words) || !LEXPAD_VERSIONS.includes(parsed.version)) {
    throw new ImportError('unrecognised');
  }

  const rows: ParsedRow[] = [];
  let skipped = 0;
  parsed.words.forEach((entry, index) => {
    const headword = clean(entry.headword);
    if (headword === '') {
      skipped += 1;
      return;
    }
    // The learning state travels beside the word in the file, not on it.
    const { progress, ...content } = entry;
    const word: ParsedRow['word'] = {
      ...content,
      headword,
      category: clean(entry.category) || 'general',
      // A word this app wrote keeps where it came from; anything else is an import.
      source: entry.source !== undefined && SOURCES.includes(entry.source) ? entry.source : 'import',
      meanings: entry.meanings ?? [],
      expressions: entry.expressions ?? [],
      collocations: entry.collocations ?? [],
      relatedWords: entry.relatedWords ?? [],
      relatedWordIds: [],
    };
    const row: ParsedRow = {
      ref: entry.id ?? String(index + 1),
      word,
      relatedRefs: entry.relatedWordIds ?? [],
    };
    if (progress !== undefined && typeof progress.box === 'number') row.progress = scheduleOnly(progress);
    if (typeof entry.createdAt === 'string') row.createdAt = entry.createdAt;
    if (typeof entry.position === 'number') row.position = entry.position;
    rows.push(row);
  });

  if (rows.length === 0) throw new ImportError('no words');
  return {
    rows,
    targetLang: asLanguageOrUndefined(parsed.notebook?.targetLang),
    meaningLang: asLanguageOrUndefined(parsed.notebook?.meaningLang),
    skipped,
  };
}

/* --------------------------------------------------------------- kindle */

/**
 * The longest highlight that can become a headword.
 *
 * A Kindle highlight is usually a sentence or a whole paragraph, which
 * belongs in a reading app rather than in a vocabulary notebook; a word, a
 * phrasal verb or a short idiom is what Lexpad is for. Anything longer is
 * counted as skipped, so the import says what it left out.
 */
const MAX_CLIPPING_WORDS = 4;

/** Entries in My Clippings.txt are separated by a line of equals signs. */
const CLIPPING_SEPARATOR = '==========';

/**
 * What the second line of a clipping calls a highlight, in the wordings
 * Kindles have used ("- Your Highlight on Location 12", the older
 * "- Highlight Loc. 12", KOReader's "- Your highlight on page 4") and in the
 * languages a Kindle is set to.
 */
const HIGHLIGHT =
  /highlight|subrayado|markierung|surlignement|evidenziazione|destaque|marca[çc][ãa]o|ハイライト|标注|標註|하이라이트|выделение|vurgu/i;
/** A note or a bookmark, which are not words the reader met. */
const NOT_HIGHLIGHT =
  /\bnote\b|\bnota\b|notiz|lesezeichen|bookmark|marcador|signet|segnalibro|メモ|ブックマーク|笔记|书签|메모|북마크|заметка|закладка/i;
/** The line under a clipping's book title: "- <kind> … | Added on …". */
const CLIPPING_META = /^\uFEFF?\s*-\s[^\n]*\|/m;

/** Whether this is a Kindle's My Clippings.txt rather than a spreadsheet. */
export function isClippings(text: string): boolean {
  return (
    text.includes(CLIPPING_SEPARATOR) &&
    CLIPPING_META.test(text) &&
    (HIGHLIGHT.test(text) || NOT_HIGHLIGHT.test(text))
  );
}

/**
 * My Clippings.txt: the book on the first line, what kind of clipping on
 * the second, and what was marked underneath.
 *
 * Only highlights become words. A bookmark holds no text, and a note is the
 * reader's own words about a highlight rather than something they met.
 */
export function parseClippings(text: string): ParsedFile {
  const rows: ParsedRow[] = [];
  let skipped = 0;
  const seen = new Set<string>();

  for (const entry of text.split(CLIPPING_SEPARATOR)) {
    const lines = entry
      .replace(/\r/g, '')
      .split('\n')
      .filter((line) => line.trim() !== '');
    if (lines.length < 3) continue;
    const kind = lines[1] ?? '';
    if (!HIGHLIGHT.test(kind) || NOT_HIGHLIGHT.test(kind.split('|')[0] ?? '')) continue;

    const marked = clean(lines.slice(2).join(' '));
    if (marked === '') continue;
    if (marked.split(/\s+/).length > MAX_CLIPPING_WORDS) {
      skipped += 1;
      continue;
    }
    const key = marked.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    rows.push({
      ref: key,
      word: {
        headword: marked,
        // The book the word was met in, so words read together stay
        // together instead of becoming one flat list.
        category: bookTitle(lines[0] ?? '') || 'general',
        source: 'import',
        // A Kindle knows the word and where it was read, never a meaning.
        meanings: [],
        expressions: [],
        collocations: [],
        relatedWords: [],
        relatedWordIds: [],
      },
      relatedRefs: [],
    });
  }

  // Every highlight was a sentence or longer: the file was read, it just
  // holds nothing that is a word, which the reader is told as such.
  if (rows.length === 0) throw new ImportError(skipped > 0 ? 'long highlights' : 'no words');
  return { rows, targetLang: undefined, meaningLang: undefined, skipped };
}

/** Drops the author from "Title (Author)", and anything absurdly long. */
function bookTitle(line: string): string {
  const title = clean(line).replace(/\s*\([^()]*\)$/, '');
  return title.length > 60 ? '' : title;
}

/* ------------------------------------------------------------------- csv */

/**
 * Two columns: the word and its meaning. A header row is ignored.
 *
 * The same reader takes a comma file, a semicolon file, a tab-separated
 * export from Quizlet and Anki's "Notes in Plain Text". The delimiter is
 * chosen once for the whole file, never per line, because a meaning is
 * full of commas: Anki's `#separator:` decides when the file has one; any
 * tab otherwise makes it a tab file; failing both, the first line decides
 * between semicolons and commas, as the server's importer does.
 */
export function parseCsv(text: string, hints?: LanguageHints): ParsedFile {
  const header = readAnkiHeader(withoutComments(text));
  // Quizlet's ";" between cards becomes a line break first; an Anki file
  // names its own separator and is never read this way.
  if (!header.anki) header.body = quizletRows(header.body) ?? header.body;
  const delimiter = header.separator ?? detectDelimiter(header.body);
  const records = (delimiter === DASH ? readDashed(header.body) : readRecords(header.body, delimiter)).map(
    (record) => record.filter((_, column) => !header.metaColumns.has(column)),
  );
  // Anki's `#columns:` names the fields; read as a header row, it places them.
  if (header.columns !== undefined)
    records.unshift(header.columns.filter((_, column) => !header.metaColumns.has(column)));
  const { rows, skipped } = readTable(records, { anki: header.anki, tabs: delimiter === '\t', hints });
  if (rows.length === 0) throw new ImportError('no words');
  return { rows, targetLang: undefined, meaningLang: undefined, skipped };
}

/**
 * A workbook's sheets, each read as a table. With more than one sheet
 * holding words, a sheet's words are filed under the sheet's name ("Unit
 * 3"), the way a Kindle's are filed under their book.
 */
export function parseSheets(
  sheets: readonly { name: string; rows: string[][] }[],
  hints?: LanguageHints,
): ParsedFile {
  const tables = sheets
    .map((sheet) => ({
      name: clean(sheet.name),
      ...readTable(sheet.rows, { anki: false, tabs: false, hints }),
    }))
    .filter((table) => table.rows.length > 0 || table.skipped > 0);
  const filled = tables.filter((table) => table.rows.length > 0);
  const rows: ParsedRow[] = [];
  let skipped = 0;
  for (const table of tables) {
    skipped += table.skipped;
    for (const row of table.rows) {
      rows.push({
        ...row,
        ref: `${table.name}:${row.ref}`,
        word: {
          ...row.word,
          category:
            filled.length > 1 && table.name !== '' && [...table.name].length <= 60 ? table.name : 'general',
        },
      });
    }
  }
  if (rows.length === 0) throw new ImportError('no words');
  return { rows, targetLang: undefined, meaningLang: undefined, skipped };
}

interface TableOptions {
  /** The rows come from a file with Anki's header. */
  anki: boolean;
  /** The rows were split at tabs (Quizlet's own export). */
  tabs: boolean;
  /** The notebook's languages, when known: a column named after one of them is placed by it. */
  hints?: LanguageHints | undefined;
}

/** The languages of the notebook a file is going into. */
export interface LanguageHints {
  targetLang: LanguageCode;
  meaningLang: LanguageCode | undefined;
}

/** Which column holds what; -1 is none. */
interface Columns {
  headword: number;
  meaning: number;
  example: number;
  pos: number;
  pronunciation: number;
  /** Read when the headword cell is empty (a kana-only word in a kanji column). */
  fallbackHeadword: number;
  /**
   * The unnamed columns right of the meaning's, under one merged header
   * ("Translation" over noun and verb columns): read, in order, when the
   * meaning cell itself is empty.
   */
  meaningSpan: number[];
}

const POSITIONAL: Columns = {
  headword: 0,
  meaning: 1,
  example: 2,
  pos: -1,
  pronunciation: -1,
  fallbackHeadword: -1,
  meaningSpan: [],
};

/**
 * Rows of cells into words: the word in the first column, its meaning in
 * the second and an example in the third, after setting aside what is not
 * a card. That is a title above the table, a column that only numbers the
 * rows ("1, abandon, …") or is empty, and a header row, which also says
 * which column is which when the sheet is laid out its own way ("english,
 * type, vietnamese, pronounce, explain, example"). A Google Translate
 * phrasebook, whose first two columns name the languages, is read from its
 * last two.
 */
function readTable(
  input: readonly string[][],
  options: TableOptions,
): { rows: ParsedRow[]; skipped: number } {
  const rows: ParsedRow[] = [];
  let skipped = 0;
  const records = withoutNumbering(withoutEmptyFirstColumn(phrasebook(input.map((record) => [...record]))));
  let columns = POSITIONAL;
  let index = 0;
  for (const [at, cells] of records.entries()) {
    if (cells.every((cell) => stripMarkup(cell) === '')) continue;
    const position = index;
    index += 1;
    // A title above a table ("Unit 3 vocabulary" alone on the first line)
    // is not a word; a header usually follows it.
    if (
      position === 0 &&
      cells.filter((cell) => stripMarkup(cell) !== '').length === 1 &&
      isTitledTable(records, at)
    ) {
      index = 0;
      continue;
    }
    // A header row names its columns rather than holding a word.
    if (position === 0) {
      const named = headerColumns(cells, options.hints);
      if (named !== undefined) {
        columns = named;
        continue;
      }
    }
    const cell = (column: number): string => (column < 0 ? '' : (cells[column] ?? ''));
    let headword = stripMarkup(cell(columns.headword)) || stripMarkup(cell(columns.fallbackHeadword));
    const meaning =
      stripMarkup(cell(columns.meaning)) ||
      (columns.meaningSpan.map((column) => stripMarkup(cell(column))).find((text) => text !== '') ?? '');
    // An example has words in it; a number in that place is a page, a
    // lesson or a level.
    let example = stripMarkup(cell(columns.example));
    if (!/\p{L}/u.test(example)) example = '';
    // A cloze card is a sentence with a gap: the gap is the word, the
    // sentence its example.
    const gaps = clozeAnswers(cell(columns.headword));
    if (gaps !== undefined) {
      headword = gaps;
      if (example === '') example = stripMarkup(cell(columns.headword));
    }
    if (headword === '' || [...headword].length > MAX_HEADWORD_CHARS) {
      // No word, or a line of prose rather than a word: the server would
      // refuse it, so it is counted here instead of failing to sync later.
      skipped += 1;
      continue;
    }
    // Quizlet writes a definition's line breaks as they are, so in its
    // tab-separated export a definition on two lines arrives as a line
    // with no tab under the card it belongs to. Anki quotes such a field,
    // so this never applies to a file with Anki's header. A single word on
    // a line of its own is still a word without a meaning yet.
    const previous = rows.at(-1);
    const prior = records[at - 1];
    if (
      options.tabs &&
      !options.anki &&
      columns === POSITIONAL &&
      cells.length === 1 &&
      /\s/.test(headword) &&
      prior !== undefined &&
      prior.length >= 2 &&
      previous?.word.meanings?.[0] !== undefined
    ) {
      const first = previous.word.meanings[0];
      first.meaning = `${first.meaning}; ${headword}`;
      records[at] = prior;
      continue;
    }
    const word: ParsedRow['word'] = {
      headword,
      category: 'general',
      source: 'import',
      meanings: meaning === '' ? [] : [{ meaning, examples: example === '' ? [] : [{ sentence: example }] }],
      expressions: [],
      collocations: [],
      relatedWords: [],
      relatedWordIds: [],
    };
    assign(word, 'pos', stripMarkup(cell(columns.pos)));
    const reading = stripMarkup(cell(columns.pronunciation));
    if (reading !== headword) assign(word, 'pronunciation', reading);
    rows.push({ ref: String(position + 1), word, relatedRefs: [] });
  }
  return { rows, skipped };
}

/**
 * The answer of a cloze ("{{c1::abandon}}"), or undefined when the text has
 * none. A note with several gaps is several cards in Anki; the first one's
 * answer is the word here, and the sentence keeps the rest.
 */
function clozeAnswers(value: string): string | undefined {
  const gaps = [...value.matchAll(/\{\{c(\d+)::([\s\S]*?)(?:::[^}]*)?\}\}/g)].map((match) => ({
    card: Number(match[1]),
    answer: stripMarkup(match[2]),
  }));
  if (gaps.length === 0) return undefined;
  const first = Math.min(...gaps.map((gap) => gap.card));
  return [
    ...new Set(gaps.filter((gap) => gap.card === first && gap.answer !== '').map((gap) => gap.answer)),
  ].join(', ');
}

/**
 * Whether the one-cell row at `at` is a title over a table: the rows after
 * it mostly have a word and a meaning. A list of single words has no title
 * to drop, so its first word stays a word.
 */
function isTitledTable(records: readonly string[][], at: number): boolean {
  const rest = records.slice(at + 1).filter((cells) => cells.some((cell) => stripMarkup(cell) !== ''));
  if (rest.length === 0) return false;
  const paired = rest.filter((cells) => cells.filter((cell) => stripMarkup(cell) !== '').length >= 2).length;
  return paired * 5 >= rest.length * 4;
}

