const COLUMN_KIND = new Map<string, keyof typeof COLUMN_NAMES>(
  (Object.entries(COLUMN_NAMES) as [keyof typeof COLUMN_NAMES, readonly string[]][]).flatMap(
    ([kind, names]) => names.map((name) => [name, kind] as const),
  ),
);

/** Every language's code, English name and own name, to the code. */
const LANGUAGE_BY_LABEL = new Map<string, LanguageCode>(
  LANGUAGES.flatMap((code) => [
    [LANGUAGE_INFO[code].name.toLowerCase(), code] as const,
    [LANGUAGE_INFO[code].native.toLowerCase(), code] as const,
  ]),
);

/** The words of a header cell: "waller_definition" is "waller" and "definition". */
function labelWords(cell: string): string[] {
  return stripMarkup(cell)
    .toLowerCase()
    .split(/[^\p{L}\p{M}\p{N}]+/u)
    .filter((part) => part !== '');
}

/** What a header cell names: a kind of column, a language, both, or nothing. */
function readLabel(cell: string): {
  kind: keyof typeof COLUMN_NAMES | undefined;
  language: LanguageCode | undefined;
} {
  const whole = stripMarkup(cell).toLowerCase();
  const words = labelWords(cell);
  const kind = words.map((part) => COLUMN_KIND.get(part)).find((found) => found !== undefined);
  const language =
    LANGUAGE_BY_LABEL.get(whole) ?? words.map((part) => LANGUAGE_BY_LABEL.get(part)).find(Boolean);
  return { kind, language };
}

/**
 * The columns a header row names, or undefined when the row is not a
 * header. A row is one when its first two cells are labels (the rule that
 * always held), or when at least two of its cells name what a column holds
 * and none of them is longer than a label.
 */
function headerColumns(cells: readonly string[], hints: LanguageHints | undefined): Columns | undefined {
  const filled = cells.map((cell) => stripMarkup(cell));
  const labels = cells.map(readLabel);
  const named = labels.filter((label) => label.kind !== undefined || label.language !== undefined).length;
  const short = filled.every(
    (cell) => cell === '' || (cell.split(/\s+/).length <= 4 && [...cell].length <= 40),
  );
  const classic = isHeader(filled[0] ?? '', filled[1] ?? '');
  if (!classic && !(named >= 2 && short)) return undefined;

  const columns: Columns = {
    headword: -1,
    meaning: -1,
    example: -1,
    pos: -1,
    pronunciation: -1,
    fallbackHeadword: -1,
    meaningSpan: [],
  };
  let definition = -1;
  const languageOnly: number[] = [];
  labels.forEach((label, column) => {
    const take = (key: Exclude<keyof Columns, 'fallbackHeadword' | 'meaningSpan'>): void => {
      if (columns[key] === -1) columns[key] = column;
    };
    // A column named after the notebook's own languages says the most:
    // "vietnamese" in a Vietnamese-meaning notebook is the meaning, even
    // beside "explain" (an English definition).
    if (label.language !== undefined && label.kind === undefined) {
      if (label.language === hints?.targetLang && columns.headword === -1) take('headword');
      else if (
        hints?.meaningLang !== undefined &&
        label.language === hints.meaningLang &&
        columns.meaning === -1
      )
        take('meaning');
      else languageOnly.push(column);
      return;
    }
    switch (label.kind) {
      case 'headword':
        take('headword');
        break;
      case 'meaning':
        take('meaning');
        break;
      case 'definition':
        if (definition === -1) definition = column;
        break;
      case 'example':
        take('example');
        break;
      case 'pos':
        take('pos');
        break;
      case 'pronunciation':
        take('pronunciation');
        break;
      default:
        break;
    }
  });
  // Columns named only by a language, in order: the word's, then the meaning's.
  for (const column of languageOnly) {
    if (columns.headword === -1) columns.headword = column;
    else if (columns.meaning === -1) columns.meaning = column;
  }
  if (columns.meaning === -1) columns.meaning = definition;
  // A sheet whose word column is named for its reading (kana) has no other.
  if (columns.headword === -1 && columns.pronunciation !== -1) {
    columns.headword = columns.pronunciation;
    columns.pronunciation = -1;
  }
  if (columns.headword !== -1 && columns.pronunciation !== -1)
    columns.fallbackHeadword = columns.pronunciation;
  // Whatever is still unplaced is read by position, as it was before.
  const unnamed = labels
    .map((label, column) => (label.kind === undefined && label.language === undefined ? column : -1))
    .filter((column) => column !== -1 && filled[column] !== '');
  if (columns.headword === -1) columns.headword = unnamed.shift() ?? 0;
  if (columns.meaning === -1) {
    const next = unnamed.find((column) => column > columns.headword);
    if (next !== undefined) columns.meaning = next;
    else if (classic) columns.meaning = 1;
  }
  if (classic && columns.example === -1 && cells.length > 2 && labels[2]?.kind === undefined)
    columns.example = 2;
  if (columns.meaning !== -1) {
    const taken = new Set([columns.headword, columns.example, columns.pos, columns.pronunciation]);
    for (
      let column = columns.meaning + 1;
      column < cells.length && filled[column] === '' && !taken.has(column);
      column += 1
    ) {
      columns.meaningSpan.push(column);
    }
  }
  return columns;
}

/** "12", "12.", "12)" or "#12": a row number rather than a word. */
const ROW_NUMBER = /^#?\d{1,7}[.)]?$/;
/** What people head a numbering column with. */
const NUMBER_HEADERS = new Set([
  '#',
  'no',
  'no.',
  'nr',
  'nr.',
  'n',
  'n°',
  'id',
  'num',
  'number',
  's/n',
  'sl',
  'ردیف',
  'شماره',
]);

/**
 * The rows without their first column, when that column only numbers them.
 * A list numbered down its first column ("1, abandon, رها کردن") would
 * otherwise import "1", "2", "3" as the words and the words as meanings.
 */
function withoutNumbering(records: string[][]): string[][] {
  const filled = records.filter((cells) => cells.some((cell) => stripMarkup(cell) !== ''));
  const first = filled[0];
  const headed = first !== undefined && NUMBER_HEADERS.has(stripMarkup(first[0]).toLowerCase());
  const body = headed ? filled.slice(1) : filled;
  const numbered = body.filter((cells) => ROW_NUMBER.test(stripMarkup(cells[0])));
  const wide = body.filter((cells) => cells.slice(1).some((cell) => stripMarkup(cell) !== ''));
  if (body.length === 0 || numbered.length * 10 < body.length * 9 || wide.length * 10 < body.length * 9)
    return records;
  return records.map((cells) => cells.slice(1));
}

/**
 * The rows without their first column, when it is empty in nearly every
 * row: a file that opens each line with its separator ("|bonjour|hello").
 */
function withoutEmptyFirstColumn(records: string[][]): string[][] {
  const filled = records.filter((cells) => cells.some((cell) => stripMarkup(cell) !== ''));
  const empty = filled.filter((cells) => cells.length > 1 && stripMarkup(cells[0]) === '').length;
  if (filled.length === 0 || empty * 10 < filled.length * 9) return records;
  return records.map((cells) => (cells.length > 1 && stripMarkup(cells[0]) === '' ? cells.slice(1) : cells));
}

/**
 * Google Translate's saved phrases, as Google Sheets or a CSV keeps them:
 * four columns, the two languages by name and then the text and its
 * translation ("English, Persian, abandon, رها کردن"), with no header.
 * Phrases saved the other way round are turned to match the rest, so the
 * word column holds one language.
 */
function phrasebook(records: string[][]): string[][] {
  const filled = records.filter((cells) => cells.some((cell) => stripMarkup(cell) !== ''));
  const isLanguage = (cell: string | undefined): boolean => LANGUAGE_LABELS.has(languageLabel(cell));
  const saved = filled.filter((cells) => cells.length >= 4 && isLanguage(cells[0]) && isLanguage(cells[1]));
  if (filled.length === 0 || saved.length * 10 < filled.length * 8) return records;
  const pairs = new Map<string, number>();
  for (const cells of saved) {
    const key = `${languageLabel(cells[0])}\u0000${languageLabel(cells[1])}`;
    pairs.set(key, (pairs.get(key) ?? 0) + 1);
  }
  const [from] = ([...pairs.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? '').split('\u0000');
  return records.map((cells) => {
    if (!(cells.length >= 4 && isLanguage(cells[0]) && isLanguage(cells[1]))) return cells;
    const [, , text = '', translation = ''] = cells;
    return languageLabel(cells[1]) === from && languageLabel(cells[0]) !== from
      ? [translation, text]
      : [text, translation];
  });
}

/** A language name as a phrasebook writes it: "Chinese (Simplified)" is Chinese. */
function languageLabel(cell: string | undefined): string {
  return stripMarkup(cell)
    .replace(/\s*\([^()]*\)$/, '')
    .toLowerCase();
}

/**
 * The directives Anki writes at the top of a plain-text export, one
 * `#key:value` per line (rslib/src/import_export/text/csv/metadata.rs).
 *
 * Only these keys, and only in the unbroken run of lines that opens the
 * file, are read as a header. Anywhere else a line starting with `#` is a
 * word like any other: `#hashtag`, `C#`, or even `#separator:tab` on the
 * fifth line of a spreadsheet is something the learner wrote down.
 */
const ANKI_KEYS = new Set([
  'separator',
  'html',
  'tags',
  'columns',
  'notetype',
  'deck',
  'notetype column',
  'deck column',
  'tags column',
  'guid column',
  'if matches',
  'match scope',
]);

/** The columns Anki can add beside a note's own fields, by their directive. */
const ANKI_META_COLUMNS = ['notetype column', 'deck column', 'tags column', 'guid column'];

/** The names Anki gives its separators; a single character means itself. */
const ANKI_SEPARATORS: Record<string, string> = {
  tab: '\t',
  comma: ',',
  semicolon: ';',
  space: ' ',
  pipe: '|',
  colon: ':',
};

const ANKI_DIRECTIVE = /^#([a-z ]+):(.*)$/i;

interface AnkiHeader {
  /** Whether the file opened with Anki's header at all. */
  anki: boolean;
  /** The file after its header lines. */
  body: string;
  separator: string | undefined;
  /** Zero-based columns holding the deck, note type, tags or id, not fields. */
  metaColumns: Set<number>;
  /** The column names `#columns:` gives, split at the file's separator. */
  columns: string[] | undefined;
}

/** Whether a file opens with an Anki header line. */
export function hasAnkiHeader(text: string): boolean {
  return ankiDirective(text.split(/\r?\n/, 1)[0] ?? '') !== undefined;
}

function ankiDirective(line: string): [string, string] | undefined {
  const match = ANKI_DIRECTIVE.exec(line.trim());
  const key = match?.[1]?.toLowerCase();
  if (match === null || key === undefined || !ANKI_KEYS.has(key)) return undefined;
  return [key, (match[2] ?? '').trim()];
}

function readAnkiHeader(text: string): AnkiHeader {
  const header: AnkiHeader = {
    anki: false,
    body: text,
    separator: undefined,
    metaColumns: new Set(),
    columns: undefined,
  };
  let columns: string | undefined;
  let offset = 0;
  while (offset < text.length) {
    const end = text.indexOf('\n', offset);
    const next = end === -1 ? text.length : end + 1;
    const directive = ankiDirective(text.slice(offset, next));
    if (directive === undefined) break;
    const [key, value] = directive;
    header.anki = true;
    if (key === 'separator') {
      header.separator = ANKI_SEPARATORS[value.toLowerCase()] ?? (value.length === 1 ? value : undefined);
    } else if (key === 'columns') {
      columns = value;
    } else if (ANKI_META_COLUMNS.includes(key)) {
      const column = Number.parseInt(value, 10);
      if (column >= 1) header.metaColumns.add(column - 1);
    }
    offset = next;
  }
  header.body = text.slice(offset);
  if (columns !== undefined && columns !== '') {
    header.columns = columns.split(header.separator ?? detectDelimiter(columns));
  }
  return header;
}

/**
 * Quizlet's export can put a semicolon between cards instead of a line
 * break ("Between rows: Semicolon"), with a tab or a comma between term and
 * definition: `caminar\tto walk;comer\tto eat;`. That text is the same set,
 * one card a line, once each semicolon is a line break; this answers it so,
 * or undefined when the text is not that shape.
 *
 * A semicolon is far more often part of a definition ("to leave; to give
 * up"), so it is taken for a row separator only when nothing else can be:
 * - text on one line, where every piece between semicolons holds the
 *   term-definition separator (a tab, or a comma when there is no tab), so
 *   `word;meaning` stays one card and `run, sprint; walk` stays a list; or
 * - text with line breaks that is plainly Quizlet's tab shape: every piece
 *   holds exactly one tab, and some line has a card's term after a
 *   semicolon, which a tab file with a card on each line never has. The
 *   line breaks are then a definition written on several lines, and become
 *   spaces.
 */
export function quizletRows(text: string): string | undefined {
  const body = text.trim();
  if (!body.includes(';')) return undefined;
  const pieces = body
    .split(';')
    .map((piece) => piece.trim())
    .filter((piece) => piece !== '');
  // One card ends with the separator too ("term\tdefinition;").
  if (pieces.length < 2 && !body.endsWith(';')) return undefined;
  if (pieces.length === 0) return undefined;
  if (!/[\r\n]/.test(body)) {
    const column = body.includes('\t') ? '\t' : ',';
    if (pieces.every((piece) => piece.includes(column))) return pieces.join('\n');
    // A definition with a semicolon of its own ("to leave; to give up")
    // leaves a piece with no separator: it belongs to the card before it.
    // That reading needs most pieces, and at least two, to be cards.
    const cards = pieces.filter((piece) => piece.includes(column)).length;
    if (!(pieces[0] ?? '').includes(column) || cards < 2 || cards * 2 < pieces.length) {
      return undefined;
    }
    const joined: string[] = [];
    for (const piece of pieces) {
      if (piece.includes(column) || joined.length === 0) joined.push(piece);
      else joined[joined.length - 1] = `${joined[joined.length - 1] ?? ''}; ${piece}`;
    }
    return joined.join('\n');
  }
  if (!body.includes('\t')) return undefined;
  const tabs = (value: string): number => value.split('\t').length - 1;
  if (!pieces.every((piece) => tabs(piece) === 1)) return undefined;
  if (!body.split(/\r?\n/).some((line) => /;.*\t/.test(line))) return undefined;
  return pieces.map((piece) => piece.replace(/\s*[\r\n]+\s*/g, ' ')).join('\n');
}

/** A spaced dash between word and meaning ("abandon - to leave"), as Quizlet's custom separator or a typed list writes it. */
const DASH = ' - ';
const DASHES = /\s[-–—=]\s/;

/**
 * Tab when the file has one, else semicolon or comma by the first line, as
 * long as most lines have it. A list whose lines are joined by a pipe or a
 * spaced dash instead is read by that.
 */
function detectDelimiter(text: string): string {
  if (text.includes('\t')) return '\t';
  const lines = text
    .split(/\r?\n|\r/)
    .filter((line) => line.trim() !== '')
    .slice(0, 200);
  const first = lines[0] ?? '';
  const count = (char: string): number => first.split(char).length - 1;
  const usual = count(';') > count(',') ? ';' : ',';
  const share = (test: (line: string) => boolean): number =>
    lines.length === 0 ? 0 : lines.filter(test).length / lines.length;
  if (share((line) => line.includes(usual)) >= 0.6) return usual;
  if (share((line) => line.includes('|')) >= 0.8) return '|';
  if (share((line) => DASHES.test(line)) >= 0.8) return DASH;
  return usual;
}

/** Lines split at their first spaced dash. */
function readDashed(text: string): string[][] {
  return text.split(/\r?\n|\r/).map((line) => {
    const match = DASHES.exec(line);
    return match === null ? [line] : [line.slice(0, match.index), line.slice(match.index + match[0].length)];
  });
}

/**
 * The file without the comment lines some published lists open with
 * ("## This list is for teaching purposes…"): a run of lines at the very
 * top that start with "#" and a space or another "#". A word that starts
 * with "#" ("#hashtag", "C#") and Anki's own "#separator:tab" stay.
 */
function withoutComments(text: string): string {
  const lines = text.split(/(?<=\n)/);
  let drop = 0;
  while (drop < lines.length && /^#(#|\s)/.test(lines[drop] ?? '')) drop += 1;
  return drop === 0 ? text : lines.slice(drop).join('');
}

/**
 * Splits a file into records of cells, honouring double quotes.
 *
 * A quote opens a quoted cell only at the start of one (after any spaces);
 * inside it, a doubled quote is a quote and the delimiter and line breaks
 * are text, which is how Anki writes a field with a newline in it. A quote
 * anywhere else, or one that never closes, is an ordinary character, so a
 * stray `5"` cannot swallow the rest of the file.
 */
function readRecords(text: string, delimiter: string): string[][] {
  const records: string[][] = [];
  let record: string[] = [];
  let cell = '';
  let quotes = true;
  let index = 0;
  while (index < text.length) {
    const char = text[index] ?? '';
    if (char === '"' && quotes && cell.trim() === '') {
      const close = closingQuote(text, index + 1);
      if (close !== -1) {
        cell = text.slice(index + 1, close).replace(/""/g, '"');
        index = close + 1;
        continue;
      }
      // No quote after this one closes anything; scanning again would only
      // repeat the same search, so the rest of the file reads them as text.
      quotes = false;
    }
    if (char === delimiter) {
      record.push(cell);
      cell = '';
    } else if (char === '\n' || char === '\r') {
      record.push(cell);
      records.push(record);
      record = [];
      cell = '';
      if (char === '\r' && text[index + 1] === '\n') index += 1;
    } else {
      cell += char;
    }
    index += 1;
  }
  record.push(cell);
  records.push(record);
  return records;
}

/** Where the quoted cell opened before `from` closes, or -1. */
function closingQuote(text: string, from: number): number {
  for (let index = from; index < text.length; index += 1) {
    if (text[index] !== '"') continue;
    if (text[index + 1] === '"') {
      index += 1;
      continue;
    }
    return index;
  }
  return -1;
}

/** The column names people give a vocabulary sheet. */
const HEADERS = new Set([
  'word',
  'words',
  'headword',
  'term',
  'front',
  'question',
  'vocabulary',
  'english',
  'meaning',
  'meanings',
  'definition',
  'translation',
  'back',
  'answer',
  'example',
  'examples',
  'sentence',
]);

/** Every language's English name and its own, lower-cased: "persian", "فارسی". */
const LANGUAGE_LABELS = new Set(
  LANGUAGES.flatMap((code) => [
    LANGUAGE_INFO[code].name.toLowerCase(),
    LANGUAGE_INFO[code].native.toLowerCase(),
  ]),
);

/**
 * Whether the first row names its columns: a label in either column, or
 * two language names ("English, Persian"), which is how a bilingual sheet
 * is usually headed.
 */
function isHeader(first: string, second: string): boolean {
  const a = first.toLowerCase();
  const b = second.toLowerCase();
  if (HEADERS.has(a) && (b === '' || HEADERS.has(b) || LANGUAGE_LABELS.has(b))) return true;
  if (HEADERS.has(b) && LANGUAGE_LABELS.has(a)) return true;
  return a !== b && LANGUAGE_LABELS.has(a) && LANGUAGE_LABELS.has(b);
}

/**
 * Card markup that is never part of a word or its meaning: an HTML tag (a
 * letter, `/` or `!` straight after the `<`, so "a < b" stays text), Anki's
 * `[sound:…]` reference, HTML entities, and the brackets of a cloze (whose
 * answer stays). Anki keeps a field's formatting
 * as HTML in its plain-text export unless told not to, and the server's
 * importer strips the same things (`format.StripHTML`).
 */
export function stripMarkup(value: string | null | undefined): string {
  let text = value ?? '';
  if (/[<[&{]/.test(text)) {
    text = text
      // A cloze shows its answer: "{{c1::abandon::verb}}" reads "abandon".
      .replace(/\{\{c\d+::([\s\S]*?)(?:::[^}]*)?\}\}/g, '$1')
      .replace(/\[sound:[^\]]*\]/g, ' ')
      // A ruby's reading sits above the word; it is not part of it.
      .replace(/<(rt|rp)\b[^>]*>[\s\S]*?<\/\1>/gi, '')
      // Inline formatting sits inside a word ("<b>run</b>ning"); a block
      // or a line break is a gap between words.
      .replace(/<\/?(b|i|u|s|em|strong|span|font|ruby|rb|sup|sub|small|mark|a)\b[^<>]*>/gi, '')
      .replace(/<[A-Za-z/!][^<>]*>/g, ' ')
      .replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (entity, name: string) => decodeEntity(entity, name));
  }
  return clean(text);
}

const ENTITIES: Record<string, string> = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };

function decodeEntity(entity: string, name: string): string {
  if (name.startsWith('#')) {
    const code =
      name[1]?.toLowerCase() === 'x'
        ? Number.parseInt(name.slice(2), 16)
        : Number.parseInt(name.slice(1), 10);
    return Number.isFinite(code) && code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : entity;
  }
  const named = ENTITIES[name.toLowerCase()];
  if (named !== undefined) return named;
  // Anything else (&eacute;, &mdash;…) the browser's own table knows.
  if (typeof document === 'undefined') return entity;
  const area = document.createElement('textarea');
  area.innerHTML = entity;
  return area.value;
}

/* ------------------------------------------------------------ direction */

/** Whether text is written in the script a language uses. */
function writtenIn(text: string, language: LanguageCode): boolean {
  const script = scriptOf(text);
  const expected = scriptOfLanguage(language);
  if (script === expected) return true;
  // Japanese is written in kana and Han; Korean sometimes in Han.
  return script === 'han' && (expected === 'kana' || expected === 'hangul');
}

/**
 * Whether a file's two columns are the wrong way round for this notebook:
 * the word column in the meaning language and the meaning column in the
 * language being learnt, as in a Quizlet set made from the learner's own
 * language. It can only tell when the two languages are written in
 * different scripts; for English and Spanish the screen offers the swap.
 */
export function looksReversed(
  rows: readonly ParsedRow[],
  target: LanguageCode,
  meaning: LanguageCode,
): boolean {
  if (scriptOfLanguage(target) === scriptOfLanguage(meaning)) return false;
  const paired = rows.filter((row) => (row.word.meanings ?? []).length > 0);
  if (paired.length === 0) return false;
  let reversed = 0;
  for (const row of paired) {
    const first = row.word.meanings?.[0]?.meaning ?? '';
    if (writtenIn(first, target) && writtenIn(row.word.headword, meaning)) reversed += 1;
  }
  return reversed * 2 > paired.length;
}

/** Whether any row has a single meaning, which is what makes swapping columns mean anything. */
export function canSwap(rows: readonly ParsedRow[]): boolean {
  return rows.some((row) => (row.word.meanings ?? []).length === 1);
}

/**
 * The same rows with word and meaning exchanged. A row with no meaning, or
 * with more than one (a Lexpad export), is left as it is; an example stays
 * with its card.
 */
export function swapColumns(rows: readonly ParsedRow[]): ParsedRow[] {
  return rows.map((row) => {
    const meanings = row.word.meanings ?? [];
    const first = meanings[0];
    if (first === undefined || meanings.length !== 1) return row;
    return {
      ...row,
      word: { ...row.word, headword: first.meaning, meanings: [{ ...first, meaning: row.word.headword }] },
    };
  });
}

/* --------------------------------------------------------------- helpers */

/** Drops entries whose headword is already in the notebook. */
export function withoutDuplicates(rows: ParsedRow[], existing: readonly string[]): ParsedRow[] {
  const seen = new Set(existing.map(normalizeHeadword));
  return rows.filter((row) => {
    const key = normalizeHeadword(row.word.headword);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function asLevel(value: string | undefined): (typeof LEVELS)[number] | undefined {
  return LEVELS.find((level) => level === value?.toUpperCase());
}

const LANGS = ['en', 'de', 'tr', 'ar', 'fr', 'es', 'fa'] as const;

function asLanguageOrUndefined(value: string | undefined): LanguageCode | undefined {
  return LANGS.find((code) => code === value);
}

function phrases(input: { en?: string; fa?: string }[] | undefined): Phrases {
  return (input ?? []).flatMap((phrase) => {
    const text = clean(phrase.en);
    if (text === '') return [];
    const translation = clean(phrase.fa);
    return [{ text, ...(translation === '' ? {} : { translation }) }];
  });
}

/** The string-valued fields a parser may fill in. */
type TextField =
  'pos' | 'pronunciation' | 'spellingNote' | 'originalMeaning' | 'correction' | 'usageNote' | 'relatedNote';

/** Sets a field only when there is something to set, never to a blank. */
function assign(word: ParsedRow['word'], key: TextField, value: string): void {
  if (value !== '') word[key] = value;
}

function clean(value: string | null | undefined): string {
  return (value ?? '').replace(/\s+/g, ' ').trim();
}

function asArray(text: string): unknown[] {
  const parsed: unknown = JSON.parse(text);
  if (!Array.isArray(parsed)) throw new ImportError('unrecognised');
  return parsed;
}

function asObject(text: string): object {
  const parsed: unknown = JSON.parse(text);
  if (typeof parsed !== 'object' || parsed === null) throw new ImportError('unrecognised');
  return parsed;
}
