/**
 * Just enough of the zip format to read a workbook and to slim an Anki
 * package, with no library: the central directory says where each entry
 * is, and entries are either stored or deflated, which the browser's own
 * DecompressionStream undoes.
 *
 * Zip64 (archives over 4 GB, or over 65,535 entries) is not read; nothing
 * a person imports as a word list comes near either.
 */
import { ImportError } from './parse.js';

export interface ZipEntry {
  name: string;
  /** 0 stored, 8 deflated; anything else cannot be read here. */
  method: number;
  compressedSize: number;
  size: number;
  crc32: number;
  /** Where the entry's local header starts. */
  offset: number;
  /** The general-purpose flags and modification time, copied as they are when re-packing. */
  flags: number;
  time: number;
  date: number;
}

const EOCD = 0x06054b50;
const CENTRAL = 0x02014b50;
const LOCAL = 0x04034b50;
/** The end record is 22 bytes plus a comment of at most 65,535. */
const EOCD_SEARCH = 22 + 0xffff;

const utf8 = new TextDecoder('utf-8');

/** Where the end record sits in `tail`, the last bytes of an archive, or -1. */
function findEnd(tail: Uint8Array): number {
  const view = new DataView(tail.buffer, tail.byteOffset, tail.byteLength);
  for (let at = tail.length - 22; at >= Math.max(0, tail.length - EOCD_SEARCH); at -= 1) {
    if (view.getUint32(at, true) === EOCD) return at;
  }
  return -1;
}

/**
 * The entries a central directory lists. `at` is where the directory
 * starts within `bytes`, which may be the whole archive or only the
 * directory itself.
 */
function readDirectory(bytes: Uint8Array, at: number, count: number): ZipEntry[] {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const entries: ZipEntry[] = [];
  for (let index = 0; index < count; index += 1) {
    if (at + 46 > bytes.length || view.getUint32(at, true) !== CENTRAL) throw new ImportError('binary');
    const nameLength = view.getUint16(at + 28, true);
    const extraLength = view.getUint16(at + 30, true);
    const commentLength = view.getUint16(at + 32, true);
    entries.push({
      flags: view.getUint16(at + 8, true),
      method: view.getUint16(at + 10, true),
      time: view.getUint16(at + 12, true),
      date: view.getUint16(at + 14, true),
      crc32: view.getUint32(at + 16, true),
      compressedSize: view.getUint32(at + 20, true),
      size: view.getUint32(at + 24, true),
      offset: view.getUint32(at + 42, true),
      name: utf8.decode(bytes.subarray(at + 46, at + 46 + nameLength)),
    });
    at += 46 + nameLength + extraLength + commentLength;
  }
  return entries;
}

/** The entries of a zip, from its central directory. Throws ImportError('binary') when it is not one. */
export function zipEntries(bytes: Uint8Array): ZipEntry[] {
  const end = findEnd(bytes);
  if (end === -1) throw new ImportError('binary');
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  return readDirectory(bytes, view.getUint32(end + 16, true), view.getUint16(end + 10, true));
}

/** A slice of a file's bytes. */
async function sliceOf(file: Blob, start: number, end: number): Promise<Uint8Array> {
  return new Uint8Array(await file.slice(start, end).arrayBuffer());
}

/**
 * The entries of a zip read from the file itself, by its last bytes and
 * its central directory only: a 200 MB Anki deck is never held in memory
 * to learn what is in it. Throws ImportError('binary') when it is not one.
 */
export async function zipEntriesOf(file: Blob): Promise<ZipEntry[]> {
  const tailStart = Math.max(0, file.size - EOCD_SEARCH);
  const tail = await sliceOf(file, tailStart, file.size);
  const end = findEnd(tail);
  if (end === -1) throw new ImportError('binary');
  const view = new DataView(tail.buffer, tail.byteOffset, tail.byteLength);
  const count = view.getUint16(end + 10, true);
  const size = view.getUint32(end + 12, true);
  const start = view.getUint32(end + 16, true);
  if (start + size > file.size) throw new ImportError('binary');
  return readDirectory(await sliceOf(file, start, start + size), 0, count);
}

/** An entry's bytes exactly as they sit in the archive (compressed, if they are). */
function rawData(bytes: Uint8Array, entry: ZipEntry): Uint8Array {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (view.getUint32(entry.offset, true) !== LOCAL) throw new ImportError('binary');
  const start =
    entry.offset + 30 + view.getUint16(entry.offset + 26, true) + view.getUint16(entry.offset + 28, true);
  const data = bytes.subarray(start, start + entry.compressedSize);
  if (data.length !== entry.compressedSize) throw new ImportError('binary');
  return data;
}

/** An entry's contents, inflated when they are deflated. */
export async function readEntry(bytes: Uint8Array, entry: ZipEntry): Promise<Uint8Array> {
  const data = rawData(bytes, entry);
  if (entry.method === 0) return data;
  if (entry.method !== 8 || typeof DecompressionStream === 'undefined') throw new ImportError('binary');
  const stream = new Blob([data as BlobPart]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
  return new Uint8Array(await new Response(stream).arrayBuffer());
}

/** An entry's contents as UTF-8 text, or undefined when the archive has no such entry. */
export async function readText(
  bytes: Uint8Array,
  entries: readonly ZipEntry[],
  name: string,
): Promise<string | undefined> {
  const entry = entries.find((candidate) => candidate.name === name);
  return entry === undefined ? undefined : utf8.decode(await readEntry(bytes, entry));
}

/**
 * A new zip holding only the named entries, copied byte for byte (still
 * compressed, with their own checksums), or undefined when none is there.
 * Nothing is inflated, so this costs a copy of what is kept and nothing of
 * what is dropped, however large.
 */
export function keepEntries(bytes: Uint8Array, keep: (name: string) => boolean): Uint8Array | undefined {
  const entries = zipEntries(bytes).filter((entry) => keep(entry.name));
  if (entries.length === 0) return undefined;
  return buildZip(entries.map((entry) => ({ entry, data: rawData(bytes, entry) })));
}

/**
 * `keepEntries` for a file read by slices: only the directory and the kept
 * entries' own bytes are read, so a deck of hundreds of megabytes of
 * pictures and sounds costs the memory of its collection alone.
 */
export async function keepEntriesOf(
  file: Blob,
  keep: (name: string) => boolean,
): Promise<Uint8Array | undefined> {
  const entries = (await zipEntriesOf(file)).filter((entry) => keep(entry.name));
  if (entries.length === 0) return undefined;
  const parts: { entry: ZipEntry; data: Uint8Array }[] = [];
  for (const entry of entries) {
    const header = await sliceOf(file, entry.offset, entry.offset + 30);
    const view = new DataView(header.buffer, header.byteOffset, header.byteLength);
    if (header.length < 30 || view.getUint32(0, true) !== LOCAL) throw new ImportError('binary');
    const start = entry.offset + 30 + view.getUint16(26, true) + view.getUint16(28, true);
    const data = await sliceOf(file, start, start + entry.compressedSize);
    if (data.length !== entry.compressedSize) throw new ImportError('binary');
    parts.push({ entry, data });
  }
  return buildZip(parts);
}

/** A zip of entries whose bytes are already as they go in the archive. */
function buildZip(kept: readonly { entry: ZipEntry; data: Uint8Array }[]): Uint8Array {
  const encoder = new TextEncoder();
  const parts: Uint8Array[] = [];
  const central: Uint8Array[] = [];
  let offset = 0;
  for (const { entry, data } of kept) {
    const name = encoder.encode(entry.name);
    // Bit 3 (sizes in a trailing descriptor) is cleared: the sizes and the
    // checksum are written into the header here, and no descriptor follows.
    const flags = entry.flags & ~0x0008;
    const local = new Uint8Array(30 + name.length);
    const lv = new DataView(local.buffer);
    lv.setUint32(0, LOCAL, true);
    lv.setUint16(4, 20, true);
    lv.setUint16(6, flags, true);
    lv.setUint16(8, entry.method, true);
    lv.setUint16(10, entry.time, true);
    lv.setUint16(12, entry.date, true);
    lv.setUint32(14, entry.crc32, true);
    lv.setUint32(18, entry.compressedSize, true);
    lv.setUint32(22, entry.size, true);
    lv.setUint16(26, name.length, true);
    lv.setUint16(28, 0, true);
    local.set(name, 30);

    const record = new Uint8Array(46 + name.length);
    const cv = new DataView(record.buffer);
    cv.setUint32(0, CENTRAL, true);
    cv.setUint16(4, 20, true);
    cv.setUint16(6, 20, true);
    cv.setUint16(8, flags, true);
    cv.setUint16(10, entry.method, true);
    cv.setUint16(12, entry.time, true);
    cv.setUint16(14, entry.date, true);
    cv.setUint32(16, entry.crc32, true);
    cv.setUint32(20, entry.compressedSize, true);
    cv.setUint32(24, entry.size, true);
    cv.setUint16(28, name.length, true);
    cv.setUint32(42, offset, true);
    record.set(name, 46);

    parts.push(local, data);
    central.push(record);
    offset += local.length + data.length;
  }
  const centralSize = central.reduce((sum, part) => sum + part.length, 0);
  const end = new Uint8Array(22);
  const ev = new DataView(end.buffer);
  ev.setUint32(0, EOCD, true);
  ev.setUint16(8, kept.length, true);
  ev.setUint16(10, kept.length, true);
  ev.setUint32(12, centralSize, true);
  ev.setUint32(16, offset, true);
  const out = new Uint8Array(offset + centralSize + end.length);
  let at = 0;
  for (const part of [...parts, ...central, end]) {
    out.set(part, at);
    at += part.length;
  }
  return out;
}
