/**
 * What kind of file somebody handed the importer, from its own first bytes.
 *
 * The name and the picker's filter say nothing reliable: a file arrives
 * under whatever name a phone or a cloud drive gave it, and a Kindle's
 * vocab.db is often copied off the device under another name. Reading a zip or a database as text is
 * what turned an Anki package into hundreds of "words" made of binary, so
 * the bytes decide before any parser sees them.
 */
import { ImportError, parseFile, parseSheets, type LanguageHints, type ParsedFile } from './parse.js';
import { readWorkbook, isWorkbook } from './xlsx.js';
import { keepEntriesOf, zipEntriesOf } from './zip.js';

export type ImportSource =
  /** Read on the server: an Anki package or collection (a zip), its media left behind. */
  | { kind: 'server'; source: 'anki'; file: File }
  /** Read on the server: a Kindle's vocab.db (SQLite). */
  | { kind: 'server'; source: 'kindle'; file: File }
  /** Text, read here: JSON, CSV/TSV, Anki or Quizlet text, My Clippings.txt. */
  | { kind: 'text'; text: string }
  /** An Excel workbook's sheets, read here. */
  | { kind: 'sheets'; sheets: { name: string; rows: string[][] }[] };

/** The words of a file read on this device. */
export function parseLocal(
  name: string,
  read: Extract<ImportSource, { kind: 'text' | 'sheets' }>,
  hints?: LanguageHints,
): ParsedFile {
  return read.kind === 'sheets' ? parseSheets(read.sheets, hints) : parseFile(name, read.text, hints);
}

const ZIP = [0x50, 0x4b, 0x03, 0x04];
const SQLITE = [...new TextEncoder().encode('SQLite format 3')];
const OLE = [0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1];

function startsWith(bytes: Uint8Array, prefix: readonly number[]): boolean {
  return prefix.every((byte, index) => bytes[index] === byte);
}

/** Office files other than an Excel workbook, which want saving as CSV first. */
const OFFICE = /\.(xlsx|xlsm|ods|numbers|docx|odt|pages)$/i;

/** What an Anki package holds that the server reads: its collection, in whichever format. */
const ANKI_COLLECTION = /^collection\.anki(2|21|21b)$/;

/** The most bytes any magic number above needs. */
const MAGIC_BYTES = 16;

/**
 * Classifies a file, reading it when this device can. Throws ImportError
 * with 'spreadsheet' for a workbook it cannot read (an .ods, a .numbers)
 * and 'binary' for anything else that is not text.
 *
 * A zip is first looked into by slices (its directory, then only what is
 * kept), never read whole: an Anki deck with its pictures and sounds can be
 * hundreds of megabytes, which a phone's web view may not be able to hold.
 */
export async function readImport(file: File): Promise<ImportSource> {
  const head = new Uint8Array(await file.slice(0, MAGIC_BYTES).arrayBuffer());
  if (startsWith(head, ZIP)) {
    let names: string[] = [];
    try {
      names = (await zipEntriesOf(file)).map((entry) => entry.name);
    } catch {
      // Not a zip this can take apart; the server says what it makes of it.
    }
    if (isWorkbook(names)) {
      try {
        return { kind: 'sheets', sheets: await readWorkbook(new Uint8Array(await file.arrayBuffer())) };
      } catch {
        throw new ImportError('spreadsheet');
      }
    }
    if (OFFICE.test(file.name)) throw new ImportError('spreadsheet');
    return { kind: 'server', source: 'anki', file: await ankiCollectionOnly(file) };
  }
  if (startsWith(head, SQLITE)) return { kind: 'server', source: 'kindle', file };
  // An Excel 97–2003 workbook (.xls) or another Office file of that age.
  if (startsWith(head, OLE)) throw new ImportError('spreadsheet');
  return { kind: 'text', text: decodeText(new Uint8Array(await file.arrayBuffer())) };
}

/**
 * An Anki package without its pictures and sounds. A shared deck is often
 * hundreds of megabytes of audio around a collection of a few, and only
 * the collection holds words; sending the rest only made the upload slow,
 * or too large for the server to take at all. The collection's own bytes
 * are copied unchanged, into memory, so what is sent no longer depends on
 * the picked file staying readable. A zip this cannot take apart goes as it
 * is, and the server says what it makes of it.
 */
async function ankiCollectionOnly(file: File): Promise<File> {
  try {
    const slim = await keepEntriesOf(file, (name) => ANKI_COLLECTION.test(name));
    if (slim === undefined || slim.length >= file.size) return file;
    return new File([slim as BlobPart], file.name, { type: 'application/zip' });
  } catch {
    return file;
  }
}

/**
 * UTF-8, or UTF-16 with a byte order mark (Excel's "Unicode Text"), or, for
 * a file in neither, the one older code page under which it reads as real
 * words. Excel on Windows still saves "CSV" in the computer's code page
 * (Windows-1252 for "café", 1256 for Persian, 1251 for Russian), so
 * refusing those refused the commonest spreadsheet export there is.
 *
 * A code page is never simply assumed: reading a Persian file as 1252
 * gives look-alike nonsense ("ÇíÑÇä"), which is worse than an error. Each
 * candidate is tried, and one is taken only when the text it gives reads
 * as words of one script each; otherwise the file is refused with a
 * request for "CSV UTF-8".
 */
export function decodeText(bytes: Uint8Array): string {
  let text: string;
  try {
    if (startsWith(bytes, [0xff, 0xfe]))
      text = new TextDecoder('utf-16le', { fatal: true }).decode(bytes.subarray(2));
    else if (startsWith(bytes, [0xfe, 0xff]))
      text = new TextDecoder('utf-16be', { fatal: true }).decode(bytes.subarray(2));
    else text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    if (bytes.includes(0)) throw new ImportError('binary');
    text = legacyText(bytes);
  }
  if (text.includes('\u0000')) throw new ImportError('binary');
  return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
}

/**
 * The code pages Excel and older systems save text in, most common first;
 * on a tie the earlier one wins. Shift_JIS and EUC-KR count only when the
 * text they give has kana or hangul, which no other reading produces.
 * Chinese code pages are not tried: Big5 and GBK both read the same bytes
 * as plausible Han, and there is no telling which is right.
 */
const CODE_PAGES = [
  'windows-1252',
  'windows-1256',
  'windows-1251',
  'windows-1250',
  'windows-1254',
  'windows-1253',
  'windows-1255',
  'macintosh',
  'shift_jis',
  'euc-kr',
] as const;

function legacyText(bytes: Uint8Array): string {
  let best: { text: string; score: number } | undefined;
  for (const label of CODE_PAGES) {
    let text: string;
    try {
      text = new TextDecoder(label, { fatal: true }).decode(bytes);
    } catch {
      continue;
    }
    if (label === 'shift_jis' && !/[\p{Script=Hiragana}\p{Script=Katakana}]/u.test(text)) continue;
    if (label === 'euc-kr' && !/\p{Script=Hangul}/u.test(text)) continue;
    const score = readability(text);
    if (score >= 0.9 && (best === undefined || score > best.score)) best = { text, score };
  }
  if (best === undefined) throw new ImportError('encoding');
  return best.text;
}

/** Punctuation outside ASCII that real text is full of. */
const COMMON_SYMBOLS =
  /[\u00a0\u00ab\u00bb\u00b0\u00b7\u00a1\u00bf\u2010-\u2027\u2030-\u203a\u20ac\u060c\u061b\u061f\u06d4\u3000-\u303f\uff01-\uff65]/u;
const SCRIPTS = [
  'Latin',
  'Arabic',
  'Cyrillic',
  'Greek',
  'Hebrew',
  'Han',
  'Hiragana',
  'Katakana',
  'Hangul',
  'Thai',
] as const;

/** The script of one letter, or undefined for a mark or anything else. */
function scriptOfLetter(char: string): string | undefined {
  return SCRIPTS.find((script) => new RegExp(`\\p{Script=${script}}`, 'u').test(char));
}

/**
 * How much of a decoding reads as text, from 0 to 1: the share of its
 * non-ASCII characters that are letters or common punctuation, times the
 * share of its non-ASCII words that look like words. A word looks wrong
 * when it mixes scripts ("caf" and an Arabic letter), when it is made only
 * of accented Latin letters (Persian read as 1252), or when a capital
 * follows a small letter inside it ("cafŽ", a Mac file read as 1252).
 */
export function readability(text: string): number {
  const foreign = [...text].filter((char) => char.charCodeAt(0) > 0x7f);
  if (foreign.length === 0) return 1;
  const fine = foreign.filter((char) => /[\p{L}\p{M}]/u.test(char) || COMMON_SYMBOLS.test(char)).length;
  const words = (text.match(/[\p{L}\p{M}]+/gu) ?? []).filter((word) => /[^\p{ASCII}]/u.test(word));
  if (words.length === 0) return fine / foreign.length;
  let good = 0;
  for (const word of words) {
    const scripts = new Set<string>();
    let ascii = false;
    let accented = 0;
    let broken = false;
    let previous = '';
    for (const char of word) {
      if (/[A-Za-z]/.test(char)) ascii = true;
      else {
        const script = scriptOfLetter(char);
        if (script !== undefined)
          scripts.add(script === 'Hiragana' || script === 'Katakana' ? 'Kana' : script);
        if (script === 'Latin') accented += 1;
        if (/\p{Lu}/u.test(char) && /\p{Ll}/u.test(previous)) broken = true;
      }
      previous = char;
    }
    const kinds = [...scripts].filter((script) => script !== 'Han' && script !== 'Kana');
    const japanese = scripts.has('Kana') || scripts.has('Han');
    const mixed =
      kinds.length > 1 ||
      (kinds.length === 1 && japanese) ||
      (ascii && (japanese || kinds.some((script) => script !== 'Latin')));
    const allAccented = !ascii && accented >= 3 && accented === [...word].length;
    if (!mixed && !allAccented && !broken) good += 1;
  }
  return (fine / foreign.length) * (good / words.length);
}
