import type { LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Button } from '@/components/ui/Button.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { canSwap, type ParsedRow } from './parse.js';
import styles from './ImportPreview.module.css';

/** How many cards the preview shows: enough to judge the columns, few enough to read. */
const PREVIEW_ROWS = 5;

/**
 * The first cards of a file as they will read, word on the left and meaning
 * on the right. Seeing three of them is how somebody notices that the
 * columns are the wrong way round, or that a meaning is still full of
 * markup, before a hundred cards are written rather than after.
 */
export function PreviewList({
  rows,
  targetLang,
  meaningLang,
}: {
  rows: readonly ParsedRow[];
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
}): React.JSX.Element {
  return (
    <ul className={styles.list} aria-label={t('import.previewLabel')}>
      {rows.slice(0, PREVIEW_ROWS).map((row) => {
        const meaning = row.word.meanings?.[0]?.meaning;
        return (
          <li key={row.ref} className={styles.item}>
            <span className={styles.word}>
              <Bilingual lang={targetLang}>{row.word.headword}</Bilingual>
            </span>
            <span className={cx(styles.meaning, meaning === undefined && styles.none)}>
              {meaning === undefined ? (
                t('import.noMeaning')
              ) : (
                <Bilingual lang={meaningLang}>{meaning}</Bilingual>
              )}
            </span>
          </li>
        );
      })}
    </ul>
  );
}

/**
 * The body of the check before an import: the count, the cards, what was
 * left out, and the swap. The caller owns the sheet and the buttons that
 * write, so Settings and the first-run screen can share it.
 */
export function ImportPreview({
  rows,
  skipped,
  alreadyHave,
  swapped,
  targetLang,
  meaningLang,
  onSwap,
}: {
  rows: readonly ParsedRow[];
  /** Entries the file held that could not become a word. */
  skipped: number;
  /** Entries already in the notebook, or repeated in the file. */
  alreadyHave: number;
  /** Whether the columns were exchanged, by the reader or by the person. */
  swapped: boolean;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  onSwap: () => void;
}): React.JSX.Element {
  return (
    <div className={styles.body}>
      <p className={styles.lead}>
        {rows.length === 1 ? t('import.foundOne') : t('import.found', { count: rows.length })}
      </p>
      <PreviewList rows={rows} targetLang={targetLang} meaningLang={meaningLang} />
      {(alreadyHave > 0 || skipped > 0) && (
        <p className={styles.note}>
          {alreadyHave > 0 && t('import.alreadyHave', { count: alreadyHave })}
          {alreadyHave > 0 && skipped > 0 && ' '}
          {skipped > 0 && t('import.skippedRows', { count: skipped })}
        </p>
      )}
      {canSwap(rows) && (
        <>
          {swapped && <p className={styles.note}>{t('import.swappedNote')}</p>}
          <Button variant="secondary" block onClick={onSwap}>
            {t('import.swap')}
          </Button>
        </>
      )}
    </div>
  );
}
